#!/usr/bin/env bash
# Builds an Audio Unit (AUv2) .component bundle on macOS from a Go main
# package that registers plugins. The binary is the same c-shared library
# as the VST3 and CLAP builds; its Info.plist lists one component per
# registered plugin (codes from plugin.AudioUnitPlugin or derived from the
# vendor and ID), generated by loading the binary with scripts/auinfo.c.
#
# usage: scripts/build_au.sh <main-package-dir> <PluginName> [output-dir]
#   scripts/build_au.sh examples/gain Gain dist
# Install by copying the bundle to ~/Library/Audio/Plug-Ins/Components.
set -euo pipefail

if [[ $# -lt 2 ]]; then
  echo "usage: $0 <main-package-dir> <PluginName> [output-dir]" >&2
  exit 2
fi

package_dir="$1"
plugin_name="$2"
script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo_root="$(cd "${script_dir}/.." && pwd)"
output_root="${3:-${repo_root}/dist}"
if [[ "$output_root" != /* ]]; then
  output_root="$(pwd)/${output_root}"
fi

if [[ "$(go env GOOS)" != "darwin" ]]; then
  echo "Audio Units build on macOS only" >&2
  exit 1
fi

bundle="${output_root}/${plugin_name}.component"
binary="${bundle}/Contents/MacOS/${plugin_name}"
bundle_id="$(printf '%s' "com.vst3go.au.${plugin_name}" | tr -c 'A-Za-z0-9.-' '-')"
# The editor's Objective-C view factory class is named after the bundle, so
# several vst3go Audio Units can share one host process.
view_class="VST3GoAUView_$(printf '%s' "$plugin_name" | tr -c 'A-Za-z0-9' '_')_$(printf '%s' "$bundle_id" | shasum | cut -c1-8)"

rm -rf "$bundle"
mkdir -p "$(dirname "$binary")" "${bundle}/Contents/Resources"
(
  cd "$repo_root"
  CGO_ENABLED=1 CGO_CFLAGS="${CGO_CFLAGS:--O2 -g} -DVST3GO_AU_VIEW_CLASS=${view_class}" \
    go build -buildmode=c-shared -trimpath -o "$binary" "./${package_dir#./}"
)
rm -f "${binary}.h"

tool_dir="$(mktemp -d)"
trap 'rm -rf "$tool_dir"' EXIT
cc -O1 -Wall "${script_dir}/auinfo.c" -o "${tool_dir}/auinfo"
components="$("${tool_dir}/auinfo" "$binary")"

cat > "${bundle}/Contents/Info.plist" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>CFBundleDevelopmentRegion</key><string>English</string>
  <key>CFBundleExecutable</key><string>${plugin_name}</string>
  <key>CFBundleIdentifier</key><string>${bundle_id}</string>
  <key>CFBundleInfoDictionaryVersion</key><string>6.0</string>
  <key>CFBundleName</key><string>${plugin_name}</string>
  <key>CFBundlePackageType</key><string>BNDL</string>
  <key>CFBundleSignature</key><string>????</string>
  <key>CFBundleVersion</key><string>1.0</string>
  <key>LSMinimumSystemVersion</key><string>10.13</string>
${components}
</dict>
</plist>
PLIST
printf 'BNDL????' > "${bundle}/Contents/PkgInfo"
plutil -lint "${bundle}/Contents/Info.plist" >/dev/null

if command -v codesign >/dev/null 2>&1; then
  codesign --force --sign - "$bundle" >/dev/null 2>&1
fi

echo "built ${bundle}"
